const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const sierraNevada = ee.Geometry.Rectangle([-121.0, 36.5, -118.0, 39.5]);
    const date1 = '2022-01-01';
    const date2 = '2022-04-01';
    const date3 = '2022-05-04';

    // 2. Data Acquisition
    const collection = ee.ImageCollection('MODIS/061/MOD10A1');
    const snowCoverBand = 'NDSI_Snow_Cover';

    // Function to get and process a single image for a date
    const getImageForDate = (date) => {
        const image = collection
            .filterDate(date, ee.Date(date).advance(1, 'day'))
            .first();
        return ee.Image(image); // Cast to handle potential null return
    };

    const imageJan1 = getImageForDate(date1);
    const imageApr1 = getImageForDate(date2);
    const imageMay4 = getImageForDate(date3);

    // 3. Data Checks and Processing
    const results = {};
    const dates = {
        'Jan_1_2022': imageJan1,
        'Apr_1_2022': imageApr1,
        'May_4_2022': imageMay4
    };

    for (const [key, image] of Object.entries(dates)) {
        // C1 Check: Check if image exists for the date
        const imageExists = ee.Algorithms.IsEqual(image, null).not();
        if (!imageExists.getInfo()) {
            console.log(`No image found for ${key}.`);
            console.log("A"); // The premise of the question is false if data is missing. Jan 1 was more than a non-existent value.
            return;
        }

        // Mask out non-snow values (clouds, fill, etc. > 100)
        const snowMask = image.select(snowCoverBand).lte(100);
        const maskedImage = image.updateMask(snowMask);

        const stats = maskedImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: sierraNevada,
            scale: 1000,
            maxPixels: 1e9
        });
        results[key] = stats.getInfo();
    }

    // 4. Validation and Calculation
    const jan_snow = results['Jan_1_2022'][snowCoverBand];
    const jan_pixels = results['Jan_1_2022'][snowCoverBand + '_count'];
    const apr_snow = results['Apr_1_2022'][snowCoverBand];
    const apr_pixels = results['Apr_1_2022'][snowCoverBand + '_count'];
    const may_snow = results['May_4_2022'][snowCoverBand];
    const may_pixels = results['May_4_2022'][snowCoverBand + '_count'];

    console.log(`Jan 1, 2022 Avg Snow Cover: ${jan_snow ? jan_snow.toFixed(2) : 'N/A'}% (Pixels: ${jan_pixels})`);
    console.log(`Apr 1, 2022 Avg Snow Cover: ${apr_snow ? apr_snow.toFixed(2) : 'N/A'}% (Pixels: ${apr_pixels})`);
    console.log(`May 4, 2022 Avg Snow Cover: ${may_snow ? may_snow.toFixed(2) : 'N/A'}% (Pixels: ${may_pixels})`);

    // C2 Check: At least one date has no valid pixels
    if (!jan_pixels || !apr_pixels || !may_pixels) {
        console.log('No valid pixels after masking for at least one date.');
        console.log("C2");
        return;
    }

    // C3 Check: Calculation resulted in null
    if (jan_snow === null || apr_snow === null || may_snow === null) {
        console.log('Calculation failed, result is null for one or more dates.');
        console.log("C3");
        return;
    }

    // 5. Final Answer
    if (jan_snow > apr_snow && jan_snow > may_snow) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
